26	/** Registrable-ish domain label, e.g. https://sub.acme.io/x -> "acme". */
27	function domainLabel(websiteUrl: string): string {
28	  try {
29	    const host = new URL(websiteUrl).hostname.replace(/^www\./, '');
30	    const parts = host.split('.');
31	    return (parts.length >= 2 ? parts[parts.length - 2]! : parts[0]!).toLowerCase();
32	  } catch {
33	    return '';
34	  }
35	}
36	
37	/** Whitespace-delimited token subsequence match, so "pricing" != "pricingx". */
38	function containsPhrase(normalized: string, phrase: string): boolean {
39	  const t = normalized.split(' ');
40	  const p = phrase.split(' ');
41	  for (let i = 0; i + p.length <= t.length; i++) {
42	    if (p.every((w, j) => t[i + j] === w)) return true;
43	  }
44	  return false;
45	}
46	
47	export function brandNavFilter(
48	  candidates: WorkingCandidate[],
49	  opts: { orgName: string; websiteUrl: string },
50	): { survivors: WorkingCandidate[]; rejected: WorkingCandidate[] } {
51	  const brand = new Set(
52	    opts.orgName
53	      .toLowerCase()
54	      .split(/\s+/)
55	      .filter((w) => w.length >= 3),
56	  );
57	  const label = domainLabel(opts.websiteUrl);
58	  if (label) brand.add(label);
59	
60	  const survivors: WorkingCandidate[] = [];
