1	import { categorizeProviderHttpStatus, isRetryableProviderError, ProviderError } from '../errors';
2	import type { LlmClient, LlmCompleteParams, LlmConfig, LlmResult } from './types';
3	
4	const DEFAULT_BASE_URL = 'https://openrouter.ai/api/v1';
5	const DEFAULT_MODEL = 'z-ai/glm-5.2';
6	const DEFAULT_TIMEOUT_MS = 60_000;
7	const DEFAULT_MAX_RETRIES = 2;
8	const DEFAULT_RETRY_DELAY_MS = 200;
9	
10	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
11	
12	function num(raw: unknown): number {
13	  return typeof raw === 'number' && Number.isFinite(raw) ? raw : 0;
14	}
15	
16	export function createOpenRouterClient(config: LlmConfig): LlmClient {
17	  const baseUrl = config.baseUrl ?? DEFAULT_BASE_URL;
18	  const defaultModel = config.defaultModel ?? DEFAULT_MODEL;
19	  const timeoutMs = config.timeoutMs ?? DEFAULT_TIMEOUT_MS;
20	  const maxRetries = config.maxRetries ?? DEFAULT_MAX_RETRIES;
21	  const retryDelayMs = config.retryDelayMs ?? DEFAULT_RETRY_DELAY_MS;
22	
23	  const headers: Record<string, string> = {
24	    Authorization: `Bearer ${config.apiKey}`,
25	    'Content-Type': 'application/json',
26	  };
27	  if (config.appReferer) headers['HTTP-Referer'] = config.appReferer;
28	  if (config.appTitle) headers['X-Title'] = config.appTitle;
29	
30	  /** One POST to /chat/completions. Handles timeout + maps failures to ProviderError. */
31	  async function once(body: Record<string, unknown>): Promise<LlmResult> {
32	    const controller = new AbortController();
33	    const timer = setTimeout(() => controller.abort(), timeoutMs);
34	    let res: Response;
35	    try {
36	      res = await fetch(`${baseUrl}/chat/completions`, {
37	        method: 'POST',
38	        headers,
39	        body: JSON.stringify(body),
40	        signal: controller.signal,
41	      });
42	    } catch (err) {
43	      if (err instanceof DOMException && err.name === 'AbortError') {
44	        throw new ProviderError('timeout', 'OpenRouter request timed out (timeout)');
45	      }
46	      throw new ProviderError('network', 'OpenRouter request failed (network)');
47	    } finally {
48	      clearTimeout(timer);
49	    }
50	
51	    if (!res.ok) {
52	      const category = categorizeProviderHttpStatus(res.status);
53	      throw new ProviderError(category, `OpenRouter request failed (${category})`);
54	    }
55	
56	    const json = (await res.json()) as {
57	      model?: string;
58	      choices?: Array<{ message?: { content?: string } }>;
59	      usage?: {
60	        prompt_tokens?: number;
61	        completion_tokens?: number;
62	        total_tokens?: number;
63	        cost?: number;
64	      };
65	    };
66	    const usage = json.usage ?? {};
67	    return {
68	      text: json.choices?.[0]?.message?.content ?? '',
69	      model: json.model ?? defaultModel,
70	      usage: {
71	        promptTokens: num(usage.prompt_tokens),
72	        completionTokens: num(usage.completion_tokens),
73	        totalTokens: num(usage.total_tokens),
74	        costUsd: typeof usage.cost === 'number' ? usage.cost : null,
75	      },
76	    };
77	  }
78	
79	  return {
80	    async complete(params: LlmCompleteParams): Promise<LlmResult> {
81	      const body: Record<string, unknown> = {
82	        model: params.model ?? defaultModel,
83	        messages: params.messages,
84	      };
