import { parseJsonObject } from '@shared/generation';
import type { LlmClient, LlmMessage } from '@shared/providers';
import { type SetupPresets, SetupPresetsSchema } from '@shared/schemas';
import { discoverBlog, fetchSite } from './scrape';

export interface ScanClients {
  llm: LlmClient;
}

function domainOf(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, '');
  } catch {
    return url;
  }
}

/**
 * Prompt for the LLM-owned preset fields. Competitors and blog URLs are handled
 * deterministically (manual entry / sitemap) and deliberately excluded here.
 */
function buildScanPrompt(url: string, pageText: string | null): LlmMessage[] {
  const system = [
    'You are an SEO onboarding assistant.',
    'From the scraped website content, produce onboarding presets as JSON.',
    'Respond with ONLY a JSON object of this exact shape:',
    '{ "business": { "name": string, "language": string, "country": string, "description": string },',
    '  "audience": { "target": string[] },',
    '  "article_preferences": {',
    '    "content_seo": { "article_style": string, "llm_instructions": string },',
    '    "engagement": { "image_style": string } } }',
    'Do NOT include competitors or blog URLs — those are handled separately.',
    'language is the primary content language (e.g. "English"); country is the primary target',
    'market as a plain country name (e.g. "United States") — never a region or "Global".',
    'description is 2-4 sentences summarizing the business.',
    'target is an array of 3-7 short, distinct audience segments (one segment per entry —',
    'never a single comma-separated sentence). article_style / image_style are short phrases.',
  ].join('\n');

  const user = pageText
    ? `Website: ${url}\n\nScraped homepage content:\n${pageText}`
    : `Website: ${url}\n\n(The homepage could not be fetched. Infer reasonable presets from the domain name "${domainOf(url)}".)`;

  return [
    { role: 'system', content: system },
    { role: 'user', content: user },
  ];
}

/**
 * Real website scanner. Scrapes the homepage + sitemap and calls the LLM to
 * generate onboarding presets. Competitors are left empty for manual entry.
 * Always returns a valid SetupPresets on success; only unparseable/invalid LLM
 * output throws (the worker then re-throws → SQS retry → DLQ).
 * See design/product-flow.md §1.1.
 */
export async function scanWebsite(url: string, { llm }: ScanClients): Promise<SetupPresets> {
  const [page, blog] = await Promise.all([fetchSite(url), discoverBlog(url)]);

  const res = await llm.complete({
    messages: buildScanPrompt(url, page?.text ?? null),
    responseFormat: 'json',
  });

  const fields = parseJsonObject(res.text) as {
    business?: unknown;
    audience?: { target?: unknown };
    article_preferences?: unknown;
  };

  // SetupPresetsSchema is the single validation gate — a malformed/incomplete
  // LLM object throws here and dead-letters rather than persisting junk.
  return SetupPresetsSchema.parse({
    business: fields.business,
    audience: { target: fields.audience?.target, competitors: [] },
    blog,
    article_preferences: fields.article_preferences,
  });
}

import { z } from 'zod';

/**
 * Onboarding presets generated by the scanner worker. All fields are
 * AI-generated suggestions the user can later edit. See design/product-flow.md §1.1.
 */
/**
 * Publishing workflow prefs (#73). Exported as a named schema so the API patch
 * bodies can reference `.partial()` — a `.default(...)`-wrapped field cannot be
 * drilled via `.shape`.
 */
export const PublishingPrefsSchema = z.object({ auto_publish: z.boolean().default(false) });

export const SetupPresetsSchema = z.object({
  business: z.object({
    name: z.string(),
    language: z.string(),
    country: z.string(),
    description: z.string(),
  }),
  audience: z.object({
    // Distinct audience segments (max 7 per design note). The preprocess keeps
    // pre-migration string documents parsing regardless of deploy ordering:
    // '' -> [], non-empty -> [string] — never comma-split, since legacy
    // strings may contain natural-language commas (#99).
    target: z.preprocess(
      (v) => (typeof v === 'string' ? (v === '' ? [] : [v]) : v),
      z.array(z.string()).max(7),
    ),
    competitors: z.array(z.string()),
  }),
  blog: z.object({
    sitemap_url: z.string(),
    main_blog_url: z.string(),
    best_articles: z.array(z.string()),
  }),
  article_preferences: z.object({
    content_seo: z.object({
      article_style: z.string(),
      // 0–3 internal links per article (frontend dropdown). Replaces the
      // pre-#73 internal_links boolean.
      internal_links_count: z.number().int().min(0).max(3).default(1),
      table_of_contents: z.boolean().default(true),
      llm_instructions: z.string(),
    }),
    engagement: z.object({
      image_style: z.string(),
      // YouTube embed toggle (#85; renamed from include_youtube_video in #73).
      youtube_videos: z.boolean().default(true),
    }),
    // Object-level default (with the field spelled out — Zod uses the default
    // value verbatim, it does NOT re-parse it) so scan output that omits
    // publishing (the LLM never produces it) still parses to auto_publish:false.
    publishing: PublishingPrefsSchema.default({ auto_publish: false }),
  }),
});
export type SetupPresets = z.infer<typeof SetupPresetsSchema>;

