1	import type { Candidate, Keyword } from '@shared/schemas';
2	import { MongoServerError } from 'mongodb';
3	import { CandidateRepo } from '../repositories/candidate.repo';
4	import { KeywordRepo } from '../repositories/keyword.repo';
5	
6	export type ScheduleConflict =
7	  | 'candidate_not_schedulable'
8	  | 'candidate_already_scheduled'
9	  | 'date_occupied'
10	  | 'keyword_already_scheduled';
11	
12	export type ScheduleResult =
13	  | { ok: true; created: boolean; keyword: Keyword }
14	  | { ok: false; reason: ScheduleConflict };
15	
16	/**
17	 * Duplicate-key check for callers outside this package (routes must not
18	 * import the Mongo driver directly).
19	 */
20	export function isDuplicateKeyError(err: unknown): boolean {
21	  return err instanceof MongoServerError && err.code === 11000;
22	}
23	
24	/** Which unique keyword index a duplicate-key error tripped. */
25	function dupKey(err: unknown): 'date' | 'keyword' | 'candidate' | null {
26	  if (!(err instanceof MongoServerError) || err.code !== 11000) return null;
27	  const kp = (err.keyPattern ?? {}) as Record<string, unknown>;
28	  if ('scheduled_date' in kp) return 'date';
29	  if ('normalized_keyword' in kp) return 'keyword';
30	  if ('candidate_id' in kp) return 'candidate';
31	  return null;
32	}
33	
34	/**
35	 * Schedule a candidate onto the planner (#99). No transactions (standalone
36	 * Mongo has none): the conditional candidate claim plus the unique keyword
37	 * indexes (org/date, org/normalized_keyword, org/candidate_id) are the
38	 * invariants, and every failure path reconciles — release the claim on a
39	 * conflict, return the existing keyword on a retry — so the operation is
40	 * idempotent and safe under concurrency. Shared by
41	 * POST /keywords/candidates/{id}/schedule and the strategy worker.
42	 */
43	export async function scheduleCandidate(
44	  candidate: Candidate,
45	  scheduledDate: string,
46	): Promise<ScheduleResult> {
47	  if (
48	    candidate.search_volume === null ||
49	    candidate.difficulty === null ||
50	    candidate.status === 'rejected'
51	  ) {
52	    return { ok: false, reason: 'candidate_not_schedulable' };
53	  }
54	
55	  // Idempotency: an existing planner entry for this candidate wins.
56	  const existing = await KeywordRepo.findByCandidateId(candidate.org_id, candidate.id);
57	  if (existing) {
58	    return existing.scheduled_date === scheduledDate
59	      ? { ok: true, created: false, keyword: existing }
60	      : { ok: false, reason: 'candidate_already_scheduled' };
61	  }
62	
63	  const claimed = await CandidateRepo.claimForScheduling(candidate.id);
64	  if (!claimed) {
65	    // Not claimable: a concurrent/prior claim, or the candidate is gone/rejected.
66	    const current = await CandidateRepo.findById(candidate.id);
67	    if (!current || current.status === 'rejected') {
68	      return { ok: false, reason: 'candidate_not_schedulable' };
69	    }
70	    const kw = await KeywordRepo.findByCandidateId(candidate.org_id, candidate.id);
71	    if (kw) {
72	      return kw.scheduled_date === scheduledDate
73	        ? { ok: true, created: false, keyword: kw }
74	        : { ok: false, reason: 'candidate_already_scheduled' };
75	    }
76	    // `selected` but no keyword: a prior attempt died between claim and insert.
77	    // Fall through and finish the job — the unique indexes arbitrate races.
78	  }
79	
80	  try {
81	    const keyword = await KeywordRepo.createFromCandidate(candidate, scheduledDate);
82	    return { ok: true, created: true, keyword };
83	  } catch (err) {
84	    const dup = dupKey(err);
85	    if (dup === null) throw err;
86	    if (dup === 'candidate') {
87	      // A concurrent request won the insert for this candidate.
88	      const kw = await KeywordRepo.findByCandidateId(candidate.org_id, candidate.id);
89	      if (kw && kw.scheduled_date === scheduledDate) {
90	        return { ok: true, created: false, keyword: kw };
91	      }
92	      return { ok: false, reason: 'candidate_already_scheduled' };
93	    }
94	    // Same-keyword retries also surface as 'keyword' (identical normalization):
95	    // treat an existing entry for this candidate as the idempotent success.
96	    if (dup === 'keyword') {
97	      const kw = await KeywordRepo.findByCandidateId(candidate.org_id, candidate.id);
98	      if (kw) {
99	        return kw.scheduled_date === scheduledDate
100	          ? { ok: true, created: false, keyword: kw }
101	          : { ok: false, reason: 'candidate_already_scheduled' };
102	      }
103	    }
104	    await CandidateRepo.releaseAfterUnschedule(candidate.id);
105	    return { ok: false, reason: dup === 'date' ? 'date_occupied' : 'keyword_already_scheduled' };
106	  }
107	}
